package thaumcraft.test;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.nbt.*;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.*;
import net.minecraft.util.ProblemReporter;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.storage.TagValueInput;
import thaumcraft.infusion.*;
import thaumcraft.content.*;
import thaumcraft.research.*;
import thaumcraft.alchemy.*;
import static thaumcraft.test.InfusionProbe.*;
public final class AdvancedInfusionChecks {
    public static final BlockPos S=new BlockPos(35,205,8);
    public static void run(ServerLevel l,ServerPlayer p){
        // Reset entities left by interrupted fixture runs before measuring an isolated source.
        for(var old:l.getEntitiesOfClass(thaumcraft.rifts.FluxRiftEntity.class,new net.minecraft.world.phys.AABB(S).inflate(12)))old.discard();
        for(var stat:List.of(net.minecraft.stats.Stats.WALK_ONE_CM,net.minecraft.stats.Stats.SPRINT_ONE_CM,net.minecraft.stats.Stats.SWIM_ONE_CM,net.minecraft.stats.Stats.JUMP))p.getStats().setValue(p,net.minecraft.stats.Stats.CUSTOM.get(stat),0);
        check(ResearchEvents.movementKnowledge(p,KnowledgeState.EMPTY).flags().isEmpty(),"Movement thresholds bypassed");p.getStats().setValue(p,net.minecraft.stats.Stats.CUSTOM.get(net.minecraft.stats.Stats.WALK_ONE_CM),160001);p.getStats().setValue(p,net.minecraft.stats.Stats.CUSTOM.get(net.minecraft.stats.Stats.SPRINT_ONE_CM),80001);p.getStats().setValue(p,net.minecraft.stats.Stats.CUSTOM.get(net.minecraft.stats.Stats.SWIM_ONE_CM),8001);p.getStats().setValue(p,net.minecraft.stats.Stats.CUSTOM.get(net.minecraft.stats.Stats.JUMP),501);check(ResearchEvents.movementKnowledge(p,KnowledgeState.EMPTY).flags().containsAll(List.of("m_walker","m_runner","m_swimmer","m_jumper")),"Movement observations did not unlock original research chain");
        var m=altar(l,B,p);float base=m.costMultiplier();check(m.cycleDelay()==5,"Base cycle changed");for(int x:new int[]{-1,1})for(int z:new int[]{-1,1})l.setBlockAndUpdate(B.offset(x,-3,z),SimpleContent.BLOCKS.get("matrix_speed").get().defaultBlockState());m.surroundings();check(m.cycleDelay()==3&&Math.abs(m.costMultiplier()-base-.04F)<.0001,"Speed upgrades not applied");for(int x:new int[]{-1,1})for(int z:new int[]{-1,1})l.setBlockAndUpdate(B.offset(x,-3,z),SimpleContent.BLOCKS.get("matrix_cost").get().defaultBlockState());m.surroundings();check(m.cycleDelay()==7&&Math.abs(m.costMultiplier()-base+.08F)<.0001,"Cost upgrades not applied");
        check(m.start(p),"Cannot start slowed infusion");for(int i=0;i<6;i++)m.serverTick();check(m.snapshot().countdown()==6,"Slowed cycle did not retain partial delay");var delayed=m.saveWithoutMetadata(l.registryAccess());m.loadWithComponents(TagValueInput.create(ProblemReporter.DISCARDING,l.registryAccess(),delayed));check(m.supported()&&m.snapshot().countdown()==6&&m.job()!=null,"Upgraded infusion could not reload countdown above five");m.abort();
        for(int x=0;x<7;x++){l.getChunkAt(S.east(x));l.setBlockAndUpdate(S.east(x).below(),Blocks.STONE.defaultBlockState());l.setBlockAndUpdate(S.east(x),Blocks.AIR.defaultBlockState());}
        l.setBlockAndUpdate(S,InfusionContent.STABILIZER.get().defaultBlockState());var source=(StabilizationEntity)l.getBlockEntity(S);for(int i=0;i<300;i++)source.serverTick();check(source.energy()==15,"Stabilizer did not charge");for(int x=1;x<=2;x++)l.setBlockAndUpdate(S.east(x),InfusionContent.INLAY.get().defaultBlockState());var ped=pedestal(l,S.east(3),new ItemStack(Items.DIAMOND));StabilizationEntity.updateCharge(l,ped.getBlockPos());check(ped.getBlockState().getValue(InfusionBlock.CHARGE)==13,"Network attenuation incorrect");check(StabilizationEntity.mitigate(l,ped.getBlockPos(),10)&&source.energy()==5&&ped.item().is(Items.DIAMOND),"Mitigation did not pay real source");check(!StabilizationEntity.mitigate(l,ped.getBlockPos(),10)&&source.energy()==5,"Insufficient mitigation spent energy");l.setBlockAndUpdate(S.east(2),Blocks.AIR.defaultBlockState());StabilizationEntity.updateCharge(l,ped.getBlockPos());check(ped.getBlockState().getValue(InfusionBlock.CHARGE)==0&&!StabilizationEntity.mitigate(l,ped.getBlockPos(),1),"Disconnected network retained energy");
        for(int i=0;i<200;i++)source.serverTick();var r=new thaumcraft.rifts.FluxRiftEntity(thaumcraft.rifts.RiftContent.RIFT.get(),l);r.setPos(S.getX()-5,S.getY()+3,S.getZ());r.setStability(0);check(l.addFreshEntity(r),"Rift not added");for(int i=0;i<5;i++)source.serverTick();check(r.stability()>0&&source.energy()<15,"Stabilizer did not stabilize real rift: stability="+r.stability()+", energy="+source.energy());r.discard();
        ResearchService.grant(p,"INFUSIONENCHANTMENT");for(var kind:InfusionEnchantments.Kind.values()){
            var tool=new ItemStack(kind==InfusionEnchantments.Kind.ARCING||kind==InfusionEnchantments.Kind.ESSENCE?Items.DIAMOND_SWORD:Items.DIAMOND_PICKAXE);tool.setDamageValue(37);tool.set(DataComponents.CUSTOM_NAME,Component.literal("Kept name"));tool.enchant(l.registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.ENCHANTMENT).getOrThrow(net.minecraft.world.item.enchantment.Enchantments.UNBREAKING),2);
            var recipe=(InfusionRecipe)l.recipeAccess().getRecipes().stream().filter(h->h.id().identifier().toString().equals("thaumcraft:infusion/enchantment_"+kind.id())).findFirst().orElseThrow().value();var book=new ItemStack(Items.ENCHANTED_BOOK);book.enchant(l.registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.ENCHANTMENT).getOrThrow(net.minecraft.world.item.enchantment.Enchantments.SHARPNESS),1);var part=recipe.components().get(1).item().items().findFirst().orElseThrow();var input=new InfusionInput(tool,List.of(book,new ItemStack(part)));check(recipe.matches(input,l),"Enchantment did not match "+kind);var result=recipe.assemble(input);check(result.getDamageValue()==37&&result.getHoverName().getString().equals("Kept name")&&result.getEnchantments().equals(tool.getEnchantments())&&InfusionEnchantments.level(result,kind)==1,"Enchant destroyed original components "+kind);if(kind.max>1){var nextInput=new InfusionInput(result,input.components());check(recipe.aspects(nextInput).entrySet().stream().allMatch(e->e.getValue()==recipe.aspects().get(e.getKey())*2),"Rank cost did not scale "+kind);}for(int i=1;i<kind.max;i++)result=InfusionEnchantments.apply(result,kind);check(!InfusionEnchantments.canApply(result,kind),"Max enchant level exceeded");check(InfusionEnchantments.apply(new ItemStack(Items.DIRT),kind).isEmpty(),"Invalid item enchanted");
        }
        var sharp=l.registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.ENCHANTMENT).getOrThrow(net.minecraft.world.item.enchantment.Enchantments.SHARPNESS);var requirement=ResearchCatalog.BY_KEY.get("INFUSIONENCHANTMENT").stages().getFirst().items().getFirst();var sword=new ItemStack(Items.IRON_SWORD);check(!requirement.matches(sword),"Unenchanted research item accepted");sword.enchant(sharp,1);check(requirement.matches(sword),"Sharpness research item rejected");
        m=altar(l,B,p);var center=(InfusionPedestal)l.getBlockEntity(B.below(2));var pick=new ItemStack(Items.DIAMOND_PICKAXE);pick.setDamageValue(37);pick.set(DataComponents.CUSTOM_NAME,Component.literal("Infused pick"));center.setItem(pick);var book=new ItemStack(Items.ENCHANTED_BOOK);book.enchant(sharp,1);((InfusionPedestal)l.getBlockEntity(B.offset(-3,-2,0))).setItem(book);((InfusionPedestal)l.getBlockEntity(B.offset(3,-2,0))).setItem(new ItemStack(Items.MAP));jar(l,B.offset(-4,-2,0),"sensus",40);jar(l,B.offset(0,-2,4),"ignis",60);jar(l,B.offset(0,-2,-4),"vinculum",1);
        var candles=LuminousContent.BLOCKS.entrySet().stream().filter(e->e.getKey().startsWith("candle_")).toList();for(int i=0;i<16;i++){int x=2+i/4,z=1+i%4;l.setBlockAndUpdate(B.offset(x,-2,z),candles.get(i).getValue().get().defaultBlockState());l.setBlockAndUpdate(B.offset(-x,-2,-z),candles.get(i).getValue().get().defaultBlockState());}
        check(m.start(p)&&AspectAmounts.total(m.job().remaining())==100,"Physical enchant infusion wrong cost");for(int i=0;i<600;i++)m.serverTick();check(m.job()==null&&InfusionEnchantments.level(center.item(),InfusionEnchantments.Kind.SOUNDING)==1&&center.item().getDamageValue()==37&&center.item().getHoverName().getString().equals("Infused pick"),"Physical enchant did not finish");
        var tag=source.saveWithoutMetadata(l.registryAccess());var restored=new StabilizationEntity(S,source.getBlockState());restored.loadWithComponents(TagValueInput.create(ProblemReporter.DISCARDING,l.registryAccess(),tag));check(restored.energy()==source.energy(),"Charge codec lost energy");
        l.setBlockAndUpdate(S.east(1),InfusionContent.INLAY.get().defaultBlockState());l.setBlockAndUpdate(S.east(2),InfusionContent.INLAY.get().defaultBlockState());ped.setItem(center.item());source.setChanged();ped.setChanged();
        thaumcraft.Thaumcraft.LOGGER.info("INFUSION_ADVANCED_RULES_OK: upgrades, attenuation, disconnects, paid mitigation, rift stabilization, all 8 enchantment recipes/limits/components, sharpness requirement, actual 100-essentia infusion");
    }
    public static void read(ServerLevel l){check(l.getBlockEntity(S) instanceof StabilizationEntity s&&s.energy()>0,"Stabilizer energy not persisted");check(l.getBlockEntity(S.east(3)) instanceof InfusionPedestal p&&InfusionEnchantments.level(p.item(),InfusionEnchantments.Kind.SOUNDING)==1&&p.item().getDamageValue()==37&&p.item().getHoverName().getString().equals("Infused pick"),"Enchanted tool did not survive restart");thaumcraft.Thaumcraft.LOGGER.info("INFUSION_ADVANCED_RESTART_OK: stored energy and full enchanted tool survived restart");}
}
